style.css:
@-moz-document domain("performancemedicine.com.au") {
/* Global */
    body {
        font-family: "Inter", Arial, sans-serif !important;
        line-height: 1.7;
        background: #ffffff;
        color: #222;
    }

    /* Header */
    header {
        background: #fff;
        box-shadow: 0 2px 10px rgba(0,0,0,.08);
    }

    /* Navigation */
    .menu a,
    nav a {
        font-weight: 600;
        color: #1d1d1d !important;
    }

    .menu a:hover,
    nav a:hover {
        color: #0094c6 !important;
    }

    /* Buttons */
    .button,
    .btn,
    input[type="submit"] {
        background: #0094c6 !important;
        color: #fff !important;
        border-radius: 6px;
        padding: 12px 24px;
        transition: .3s;
    }

    .button:hover,
    .btn:hover {
        background: #0079a3 !important;
    }

    /* Service Cards */
    .service,
    .service-card,
    .elementor-widget-container {
        border-radius: 12px;
    }

    /* Images */
    img {
        border-radius: 10px;
    }

    /* Footer */
    footer {
        background: #111;
        color: #eee;
    }

    footer a {
        color: #fff;
    }

    footer a:hover {
        color: #00b4e6;
    }
}
